{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "In patients with cirrhosis, bumetanide—a loop diuretic with a sulfonamide/sulfamoyl aryl system—showed 95% oral bioavailability; this is the closest therapeutic and chemical anchor and directly supports high F for the query under the same condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tolfenamic acid in patients with alcoholic cirrhosis had about 100% absolute oral bioavailability, demonstrating that cirrhosis can preserve or increase systemic availability of hepatically cleared drugs and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Isradipine, whose healthy-subject bioavailability is only about 17%, rose to 36.9% in cirrhosis, showing that even high-first-pass drugs can exceed the 20% threshold under the query condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Bumetanide in healthy volunteers had 96% oral bioavailability, confirming high intrinsic absorption for a close loop-diuretic analogue and supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Esaxerenone, a small-molecule drug with high permeability, had 89% absolute bioavailability in the fasting state, corroborating that well-absorbed small molecules in this size and polarity range are typically high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a pyridine-sulfonylurea loop-diuretic-like molecule. The closest analogue, bumetanide, shows high oral bioavailability in healthy subjects and in cirrhosis (95%), and other cirrhosis-specific records also show F values well above 20%. No affirmative threshold-relevant evidence supports low bioavailability for this compound class under cirrhosis.",
  "evidence_gaps": [
    "No direct bioavailability record for the exact query molecule was supplied; prediction relies on close analogues.",
    "Cirrhosis-specific data are available for bumetanide and tolfenamic acid but not for the exact sulfonylurea query.",
    "Low-F records in the evidence set come from structurally unrelated molecules or non-cirrhotic conditions and are not transferable to this query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

